<?php foreach($catalog as $element=>$label):?><section class="panel typography-element"><header><div><span class="panel-kicker">Typography</span><h2><?=e($label)?></h2></div><code><?=e($element)?></code></header><div class="typography-device-grid"><?php foreach($devices as $device=>$deviceLabel):$d=$defaults[$element][$device];?><fieldset><legend><?=e($deviceLabel)?></legend><label>Font Family<select name="typography_<?=$element?>_<?=$device?>_family"><?php foreach($families as $id=>$family):?><option value="<?=$id?>" <?=$value("typography_{$element}_{$device}_family",$d['family'])===$id?'selected':''?>><?=e($family)?></option><?php endforeach;?></select></label><div class="typography-number-grid"><label>Size <span>px</span><input type="number" min="10" max="120" name="typography_<?=$element?>_<?=$device?>_size" value="<?=e($value("typography_{$element}_{$device}_size",$d['size']))?>"></label><label>Weight<select name="typography_<?=$element?>_<?=$device?>_weight"><?php foreach($weights as $weight):?><option value="<?=$weight?>" <?=$value("typography_{$element}_{$device}_weight",$d['weight'])==(string)$weight?'selected':''?>><?=$weight?></option><?php endforeach;?></select></label><label>Line Height<input type="number" step="0.05" min="0.8" max="3" name="typography_<?=$element?>_<?=$device?>_line" value="<?=e($value("typography_{$element}_{$device}_line",$d['line']))?>"></label><label>Letter Spacing <span>px</span><input type="number" step="0.1" min="-5" max="20" name="typography_<?=$element?>_<?=$device?>_letter" value="<?=e($value("typography_{$element}_{$device}_letter",$d['letter']))?>"></label><label>Word Spacing <span>px</span><input type="number" step="0.1" min="-5" max="30" name="typography_<?=$element?>_<?=$device?>_word" value="<?=e($value("typography_{$element}_{$device}_word",$d['word']))?>"></label></div></fieldset><?php endforeach;?></div></section><?php endforeach;?>
